import 'package:flutter/material.dart';
import 'dashboard_service.dart';

class TeacherDashboard extends StatefulWidget { const TeacherDashboard({super.key}); @override State<TeacherDashboard> createState()=>_TeacherDashboardState(); }
class _TeacherDashboardState extends State<TeacherDashboard>{final service=DashboardService();bool loading=true;String? error;Map<String,dynamic> data={};@override void initState(){super.initState();_load();}Future<void> _load()async{try{final d=await service.teacherOverview();if(mounted)setState((){data=d;loading=false;});}catch(e){if(mounted)setState((){error=e.toString();loading=false;});}}@override Widget build(BuildContext c){if(loading)return const Center(child:CircularProgressIndicator());if(error!=null)return Center(child:Text(error!));final sections=(data['sections'] as List?)??const [];return RefreshIndicator(onRefresh:_load,child:ListView(padding:const EdgeInsets.all(16),children:[Text('Teacher Dashboard',style:Theme.of(c).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.w800)),const SizedBox(height:12),Row(children:[Expanded(child:_stat(c,'Classes',sections.length,Icons.class_)),Expanded(child:_stat(c,'Students',data['studentCount']??0,Icons.groups))]),const SizedBox(height:12),...sections.asMap().entries.map((e)=>TweenAnimationBuilder<double>(tween:Tween(begin:0,end:1),duration:Duration(milliseconds:300+e.key*70),builder:(ctx,v,child)=>Opacity(opacity:v,child:Transform.translate(offset:Offset(0,14*(1-v)),child:child)),child:Card(child:ListTile(leading:const CircleAvatar(child:Icon(Icons.groups)),title:Text('${e.value['className']??'Class'} • ${e.value['sectionName']??''}'),subtitle:Text('${e.value['studentCount']??0} students'),trailing:const Icon(Icons.chevron_right)))))]));}Widget _stat(BuildContext c,String t,d,IconData i)=>Card(child:Padding(padding:const EdgeInsets.all(14),child:Row(children:[Icon(i,size:28),const SizedBox(width:10),Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(t,style:Theme.of(c).textTheme.bodySmall),Text('$d',style:Theme.of(c).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.w800))])])));}
